#!/usr/bin/env bash
# bin/coding-rules-check.sh — enforces WB Listora-specific coding rules.
#
# Run via: composer coding-rules
#         (or directly: bash bin/coding-rules-check.sh)
#
# Each rule has its own check function. On violation the script appends a
# line to $VIOLATIONS_FILE and exits 1 at the end. Exit 0 = all rules pass.
#
# Generated by wp-plugin-onboard skill. Customize each check for your
# plugin's specific rules — the two below are the most-common patterns:
#   1. Native current_user_can() with a custom-ability slug (broken when
#      abilities have default_roles=[] — common in custom-RBAC plugins)
#   2. REST __return_true outside an explicit allowlist (security gate
#      against silently-public endpoints)

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

VIOLATIONS_FILE="$(mktemp)"
trap 'rm -f "$VIOLATIONS_FILE"' EXIT

violation() {
    echo "✗ $*"
    echo "v" >> "$VIOLATIONS_FILE"
}
ok() { echo "✓ $*"; }
violations_count() { wc -l < "$VIOLATIONS_FILE" | tr -d ' '; }

# ------------------------------------------------------------------------------

# Rule 1: never use current_user_can() with a custom-ability slug.
# Architecture: if your plugin registers abilities with empty default_roles
# (common in custom RBAC), current_user_can('plugin/foo') returns false
# for everyone. The plugin's own Permission_Engine (or equivalent) is the
# only correct gate.
#
# Customize: replace wb_listora with your plugin's ability namespace.
check_no_native_cap_check_for_plugin_abilities() {
    local hits
    hits=$(grep -rEn "current_user_can\(\s*['\"]wb_listora/" "$PLUGIN_DIR/includes/" 2>/dev/null \
            | grep -vE "Permission_Engine|class-abilities\.php|/CHANGELOG|/tests/" \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 1 — current_user_can('wb_listora/...') outside Permission_Engine:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: route the check through your plugin's Permission_Engine."
    else
        ok "Rule 1 — no native cap checks for wb_listora/* abilities"
    fi
}

# Rule 2: REST permission_callback must not use the bare '__return_true'
# string outside the allowlist of intentionally-public controllers (auth,
# catalog, certificate verification, third-party webhooks).
#
# Customize: list every controller file that legitimately ships
# __return_true. Document the reason in audit/FEATURE_AUDIT.md §3.
check_unauthenticated_rest_allowlist() {
    local allowed_files=(
        # Public READ-only directory data — visitors must be able to
        # browse listings, search, and inspect related metadata without
        # logging in. Each entry below ONLY exposes GET endpoints that
        # surface already-public listing data; mutations (POST/PUT/DELETE)
        # in the same controllers are gated by named permission methods.
        # See audit/FEATURE_AUDIT.md §3 for per-route justification.
        'class-listings-controller.php'        # GET /listings/{id}, /related, POST /bulk (read-only IDs)
        'class-listing-types-controller.php'   # GET /listing-types/* (catalog)
        'class-search-controller.php'          # GET /search, /search/suggest
        'class-services-controller.php'        # GET /services per listing (public detail tab)
        'class-reviews-controller.php'         # GET /listings/{id}/reviews (public reviews)
        'class-settings-controller.php'        # GET /settings/map, /settings/app-config (frontend bootstrap)
        'class-submission-controller.php'      # POST /submission/resend-verification, GET /verify (token-gated, no session needed)
    )

    if [ ${#allowed_files[@]} -eq 0 ]; then
        # No allowlist defined — only flag if there are any __return_true uses.
        local hits
        hits=$(grep -rEn "permission_callback['\"]?[[:space:]]*=>[[:space:]]*['\"]__return_true['\"]" "$PLUGIN_DIR/includes/" 2>/dev/null \
                | grep -vE "/tests/|class-abilities\\.php" || true)
        if [ -n "$hits" ]; then
            violation "Rule 2 — __return_true permission_callback found, no allowlist defined yet:"
            echo "$hits" | sed 's/^/    /'
            echo "    Fix: add the controller file to allowed_files[] in this script,"
            echo "         OR replace with a named permission method that returns true|WP_Error."
        else
            ok "Rule 2 — no __return_true REST callbacks"
        fi
        return
    fi

    local exclude_pattern
    exclude_pattern=$( IFS='|' ; echo "${allowed_files[*]}" )

    local hits
    hits=$(grep -rEn "permission_callback['\"]?[[:space:]]*=>[[:space:]]*['\"]__return_true['\"]" "$PLUGIN_DIR/includes/" 2>/dev/null \
            | grep -vE "$exclude_pattern" \
            || true)

    if [ -n "$hits" ]; then
        violation "Rule 2 — __return_true on a non-allowlisted REST endpoint:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: replace with a named permission method that returns true|WP_Error,"
        echo "         OR add this controller to the allowlist + document in"
        echo "         audit/FEATURE_AUDIT.md §3 if the route is intentionally public."
    else
        ok "Rule 2 — REST __return_true usage is on the allowlist only"
    fi
}

# Rule 3: the de-hardened CSS layers must stay !important-free.
# The button vocabulary + component controls achieve theme-independence via
# clean scoped specificity (doubled-class), NOT !important — Listora renders
# outside .entry-content so theme anchor resets never reach it. A reappearing
# !important declaration here means someone reintroduced a theme-fighting hack.
# Matches the declaration form (`!important;` / `!important}`) so prose mentions
# of "no !important" in comments don't trip it.
check_no_important_in_clean_css() {
    local files=(
        "src/components/button.css"
        "src/components/theme-hardening.css"
    )
    local hits=""
    local f m
    for f in "${files[@]}"; do
        [ -f "$PLUGIN_DIR/$f" ] || continue
        m=$(grep -nE '!important[[:space:]]*[;}]' "$PLUGIN_DIR/$f" 2>/dev/null || true)
        [ -n "$m" ] && hits="${hits}${f}:"$'\n'"${m}"$'\n'
    done
    if [ -n "$hits" ]; then
        violation "Rule 3 — !important reintroduced in the clean CSS layer:"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: use clean scoped specificity (doubled-class), not !important."
    else
        ok "Rule 3 — clean CSS layer (button.css, theme-hardening.css) is !important-free"
    fi
}

# Rule 4: compiled CSS must match a fresh build from src/ (drift guard).
# The whole "hand-edited the compiled file, source rotted" class of bug is
# what build-css.mjs --check prevents: assets/css/listora-{variables,components}.css
# are GENERATED — edit src/ and run `npm run build:css`, never hand-edit them.
check_css_build_in_sync() {
    if [ ! -f "$PLUGIN_DIR/bin/build-css.mjs" ]; then
        return
    fi
    if ! command -v node >/dev/null 2>&1; then
        ok "Rule 4 — CSS drift check skipped (node not available)"
        return
    fi
    if node "$PLUGIN_DIR/bin/build-css.mjs" --check >/dev/null 2>&1; then
        ok "Rule 4 — compiled CSS matches src/ (no drift)"
    else
        violation "Rule 4 — compiled CSS out of sync with src/ (drift):"
        node "$PLUGIN_DIR/bin/build-css.mjs" --check 2>&1 | grep '✗' | sed 's/^/    /'
        echo "    Fix: run 'npm run build:css' and commit the regenerated files."
    fi
}

# Rule 5: never emit the wp-element-button class. It couples Listora buttons to
# themes' :not(.wp-element-button) anchor-reset exclusion — a theme-fighting
# hack. Theme-independence comes from clean scoped specificity instead.
check_no_wp_element_button() {
    local hits
    hits=$(grep -rIn "wp-element-button" "$PLUGIN_DIR/templates" "$PLUGIN_DIR/blocks" "$PLUGIN_DIR/src" \
            --include='*.php' --include='*.js' 2>/dev/null \
            | grep -vE "/build/|:not\(\.wp-element-button\)|theme-isolation|wp-element-button gate" \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 5 — wp-element-button emitted in markup (theme-coupling hack):"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: drop wp-element-button; rely on the .listora-btn scoped vocabulary."
    else
        ok "Rule 5 — no wp-element-button in markup"
    fi
}

# Rule 6: no inline <style>/<script> in PHP. All CSS via enqueued stylesheets,
# all JS via enqueued scripts + wp_localize_script. Documented exceptions:
# email templates (HTML email needs inline), the coming-soon pre-bootstrap
# splash, Block_CSS per-instance scoped <style>, JSON-LD structured data
# (`application/ld+json` — data, not executable JS), and prose mentions of
# "inline <script>" in code comments.
check_no_inline_style_script_in_php() {
    local hits
    hits=$(grep -rIn '<style\|<script' "$PLUGIN_DIR/templates" "$PLUGIN_DIR/blocks" "$PLUGIN_DIR/includes" \
            --include='*.php' 2>/dev/null \
            | grep -vE "/emails?/|class-block-css|coming-soon|email-verification|oauth|window\.opener|wp_add_inline|application/ld\+json|inline <s|:[0-9]+:[[:space:]]*//|:[0-9]+:[[:space:]]*\*" \
            || true)
    if [ -n "$hits" ]; then
        violation "Rule 6 — inline <style>/<script> in PHP (must be enqueued):"
        echo "$hits" | sed 's/^/    /'
        echo "    Fix: enqueue CSS/JS, or use wp_add_inline_style / Block_CSS for dynamic values."
    else
        ok "Rule 6 — no inline <style>/<script> in PHP (outside documented exceptions)"
    fi
}

# ------------------------------------------------------------------------------

echo "=== WB Listora coding-rules check ==="
echo "Plugin: $PLUGIN_DIR"
echo ""

check_no_native_cap_check_for_plugin_abilities
check_unauthenticated_rest_allowlist
check_no_important_in_clean_css
check_css_build_in_sync
check_no_wp_element_button
check_no_inline_style_script_in_php

echo ""
COUNT=$(violations_count)
if [ "$COUNT" -eq 0 ]; then
    echo "All coding rules pass."
    exit 0
else
    echo "$COUNT violation(s) found. See CLAUDE.md \"Important patterns\"."
    exit 1
fi
